using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace Generator;

[Generator]
public class RegisterChildClassGenerator : IIncrementalGenerator
{
    private const string AttributeSource = @"
// <auto-generated/>
using System;
/// <summary>
/// 注册该类所有具有无参构造函数的叶子结点子类到对应的管理器
/// </summary>
[AttributeUsage(AttributeTargets.Class, AllowMultiple = false, Inherited = false)]
internal sealed class RegisterChildClassAttribute : Attribute
{
    public RegisterChildClassAttribute()
    {
    }
}
";

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(ctx =>
            ctx.AddSource("RegisterChildClassAttribute.g.cs", SourceText.From(AttributeSource, Encoding.UTF8)));

        var baseClasses = context.SyntaxProvider
            .CreateSyntaxProvider(
                predicate: static (node, _) => node is ClassDeclarationSyntax,
                transform: static (ctx, _) => GetBaseClassInfo(ctx))
            .Where(static info => info is not null)
            .Select(static (info, _) => info!)
            .Collect();

        context.RegisterSourceOutput(baseClasses.Combine(context.CompilationProvider),
            (spc, tuple) => Execute(spc, tuple.Left, tuple.Right));
    }

    private static INamedTypeSymbol? GetBaseClassInfo(GeneratorSyntaxContext context)
    {
        var classDecl = (ClassDeclarationSyntax)context.Node;
        var model = context.SemanticModel;
        var classSymbol = model.GetDeclaredSymbol(classDecl) as INamedTypeSymbol;
        if (classSymbol == null) return null;

        foreach (var attr in classSymbol.GetAttributes())
        {
            if (attr.AttributeClass?.Name == "RegisterChildClassAttribute")
            {
                return classSymbol;
            }
        }
        return null;
    }

    private static void Execute(SourceProductionContext spc,
        ImmutableArray<INamedTypeSymbol> baseClasses,
        Compilation compilation)
    {
        if (baseClasses.IsDefaultOrEmpty) return;

        var allTypes = GetAllTypes(compilation.GlobalNamespace);
        var derivedMap = BuildDerivedMap(allTypes);

        var registrations = new List<(string LeafFullName, string RegistrationMethod)>();
        foreach (var baseClass in baseClasses)
        {
            var leafClasses = FindLeafClasses(baseClass, derivedMap);
            foreach (var leaf in leafClasses)
            {
                var leafFull = leaf.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
                
                // 根据子类的继承链确定注册方法
                string registrationMethod = DetermineRegistrationMethod(leaf, compilation);
                
                registrations.Add((leafFull, registrationMethod));
            }
        }

        if (registrations.Count == 0) return;

        // 获取程序集名称作为默认命名空间
        string assemblyName = compilation.AssemblyName ?? "Generated";
        // 可选：清理命名空间中的非法字符（通常点号是合法的）
        string ns = assemblyName.Trim();

        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated/>");
        sb.AppendLine("#nullable enable");
        sb.AppendLine("using TheBlockWar.Scripts.Resources;");
        sb.AppendLine("using TheBlockWar.Scripts.Games.Buffs;");
        sb.AppendLine("using TheBlockWar.Scripts.Games.Regions;");
        sb.AppendLine("using TheBlockWar.Scripts.Games.Skills;");
        sb.AppendLine();

        // 如果命名空间不为空，则包装
        if (!string.IsNullOrEmpty(ns))
        {
            sb.AppendLine($"namespace {ns}");
            sb.AppendLine("{");
        }

        sb.AppendLine("    public static class Registerer");
        sb.AppendLine("    {");
        sb.AppendLine("        ");
        sb.AppendLine("        public static void Register(InfoManager infoManager)");
        sb.AppendLine("        {");

        foreach (var (leafFull, registrationMethod) in registrations)
        {
            if (registrationMethod != "Unknown") // Skip unknown types
            {
                sb.AppendLine($"            {registrationMethod}(infoManager, new {leafFull}());");
            }
        }

        sb.AppendLine("        }");
        
        sb.AppendLine("        ");
        sb.AppendLine("        public static void RegisterBuff(InfoManager infoManager, IBuff buff)");
        sb.AppendLine("        {");
        sb.AppendLine("            if (!infoManager.BuffInfos.TryGetValue(buff.Name, out var buffInfo)) return;");
        sb.AppendLine("            buffInfo.Hook = buff;");
        sb.AppendLine("        }");
        sb.AppendLine("        ");
        sb.AppendLine("        public static void RegisterRegion(InfoManager infoManager, IRegion region)");
        sb.AppendLine("        {");
        sb.AppendLine("            if (!infoManager.RegionInfos.TryGetValue(region.Name, out var regionInfo)) return;");
        sb.AppendLine("            regionInfo.Hook = region;");
        sb.AppendLine("        }");
        sb.AppendLine("        ");
        sb.AppendLine("        public static void RegisterSkill(InfoManager infoManager, ISkill skill)");
        sb.AppendLine("        {");
        sb.AppendLine("            if (!infoManager.SkillInfos.TryGetValue(skill.SkillName, out var skillInfo)) return;");
        sb.AppendLine("            skillInfo.Instance = skill;");
        sb.AppendLine("        }");
        
        sb.AppendLine("    }");

        if (!string.IsNullOrEmpty(ns))
            sb.AppendLine("}");

        spc.AddSource("Registerer.g.cs", SourceText.From(sb.ToString(), Encoding.UTF8));
    }

    private static ImmutableArray<INamedTypeSymbol> GetAllTypes(INamespaceSymbol ns)
    {
        var builder = ImmutableArray.CreateBuilder<INamedTypeSymbol>();
        CollectTypes(ns, builder);
        return builder.ToImmutable();
    }

    private static void CollectTypes(INamespaceOrTypeSymbol symbol, ImmutableArray<INamedTypeSymbol>.Builder builder)
    {
        foreach (var member in symbol.GetMembers())
        {
            if (member is INamedTypeSymbol type)
            {
                builder.Add(type);
                CollectTypes(type, builder);
            }
            else if (member is INamespaceSymbol childNs)
            {
                CollectTypes(childNs, builder);
            }
        }
    }

    private static Dictionary<INamedTypeSymbol, List<INamedTypeSymbol>> BuildDerivedMap(ImmutableArray<INamedTypeSymbol> allTypes)
    {
        var map = new Dictionary<INamedTypeSymbol, List<INamedTypeSymbol>>(SymbolEqualityComparer.Default);
        foreach (var type in allTypes)
        {
            if (type.TypeKind != TypeKind.Class || type.IsAbstract) continue;
            var baseType = type.BaseType;
            while (baseType != null)
            {
                if (!map.TryGetValue(baseType, out var list))
                {
                    list = new List<INamedTypeSymbol>();
                    map[baseType] = list;
                }
                list.Add(type);
                baseType = baseType.BaseType;
            }
        }
        return map;
    }

    private static ImmutableArray<INamedTypeSymbol> FindLeafClasses(INamedTypeSymbol baseClass,
        Dictionary<INamedTypeSymbol, List<INamedTypeSymbol>> derivedMap)
    {
        var leafs = new List<INamedTypeSymbol>();
        var candidates = new Stack<INamedTypeSymbol>();
        candidates.Push(baseClass);

        while (candidates.Count > 0)
        {
            var current = candidates.Pop();
            if (derivedMap.TryGetValue(current, out var children))
            {
                foreach (var child in children)
                {
                    candidates.Push(child);
                }
            }
            else
            {
                // 叶子类：必须满足以下条件
                // 1. 是类类型且非抽象
                // 2. 不是基类自身
                // 3. 拥有公共无参构造函数
                if (current.TypeKind == TypeKind.Class &&
                    !current.IsAbstract &&
                    !SymbolEqualityComparer.Default.Equals(current, baseClass) &&
                    HasParameterlessConstructor(current))
                {
                    leafs.Add(current);
                }
            }
        }
        return leafs.ToImmutableArray();
    }

    private static bool HasParameterlessConstructor(INamedTypeSymbol type)
    {
        foreach (var ctor in type.Constructors)
        {
            if (ctor.Parameters.Length == 0 && ctor.DeclaredAccessibility == Accessibility.Public)
                return true;
        }
        return false;
    }
    
    private static string DetermineRegistrationMethod(INamedTypeSymbol leafClass, Compilation compilation)
    {
        // 获取相关的接口类型
        var ibuffType = compilation.GetTypeByMetadataName("TheBlockWar.Scripts.Games.Buffs.IBuff");
        var iregionType = compilation.GetTypeByMetadataName("TheBlockWar.Scripts.Games.Regions.IRegion");
        var iskillType = compilation.GetTypeByMetadataName("TheBlockWar.Scripts.Games.Skills.ISkill");
        
        // 检查继承链中是否有实现特定接口
        if (ImplementsInterface(leafClass, ibuffType))
        {
            return "RegisterBuff";
        }
        else if (ImplementsInterface(leafClass, iregionType))
        {
            return "RegisterRegion";
        }
        else if (ImplementsInterface(leafClass, iskillType))
        {
            return "RegisterSkill";
        }
        
        // 如果没有匹配的特殊接口，返回未知（不会生成注册代码）
        return "Unknown";
    }
    
    private static bool ImplementsInterface(INamedTypeSymbol type, INamedTypeSymbol? interfaceType)
    {
        if (interfaceType == null) return false;
        
        // 检查当前类型是否直接实现接口
        foreach (var iface in type.AllInterfaces)
        {
            if (SymbolEqualityComparer.Default.Equals(iface, interfaceType))
            {
                return true;
            }
        }
        
        // 检查基类是否实现接口
        var baseType = type.BaseType;
        while (baseType != null && baseType.SpecialType != SpecialType.System_Object)
        {
            foreach (var iface in baseType.AllInterfaces)
            {
                if (SymbolEqualityComparer.Default.Equals(iface, interfaceType))
                {
                    return true;
                }
            }
            baseType = baseType.BaseType;
        }
        
        return false;
    }
}